import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";

const API_URL = process.env.REACT_APP_API_URL || "http://localhost:5005";

const MACHINES_PER_PAGE = 20;

function Dashboard() {
  const [alerts, setAlerts] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [connectionStatus, setConnectionStatus] = useState("Connecting...");

  // =========================================================
  // FETCH MACHINE DATA
  // =========================================================

  useEffect(() => {
    const fetchAlerts = async () => {
      try {
        setLoading(true);

        const response = await fetch(`${API_URL}/api/alerts`);

        if (!response.ok) {
          throw new Error("Failed to fetch machine data");
        }

        const data = await response.json();

        setAlerts(data);
        setConnectionStatus("Backend Connected");
      } catch (error) {
        console.error("Fetch alerts error:", error);
        setConnectionStatus("Backend Error");
      } finally {
        setLoading(false);
      }
    };

    fetchAlerts();
  }, []);

  // =========================================================
  // SOCKET.IO - REAL TIME MACHINE DATA
  // =========================================================

  useEffect(() => {
    const socket = io(API_URL, {
      transports: ["websocket", "polling"],
    });

    socket.on("connect", () => {
      console.log("Socket connected:", socket.id);

      setConnectionStatus("Live Connected");
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected");

      setConnectionStatus("Disconnected");
    });

    socket.on("connect_error", (error) => {
      console.error("Socket connection error:", error);

      setConnectionStatus("Socket Error");
    });

    socket.on("alert", (newAlert) => {
      console.log("New machine received:", newAlert);

      setAlerts((previousAlerts) => {
        const exists = previousAlerts.some(
          (alert) => alert._id === newAlert._id,
        );

        if (exists) {
          return previousAlerts;
        }

        // Add newest machine at beginning
        return [newAlert, ...previousAlerts];
      });
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  // =========================================================
  // CRITICAL / NORMAL COUNT
  // =========================================================

  const criticalCount = alerts.filter(
    (alert) =>
      alert.status === "CRITICAL FAULT PREDICTED" ||
      alert.status === "CRITICAL FAULT",
  ).length;

  const normalCount = alerts.length - criticalCount;

  // =========================================================
  // GRAPH DATA
  // =========================================================

  const chartData = [
    {
      name: "Normal",
      value: normalCount,
    },
    {
      name: "Critical",
      value: criticalCount,
    },
  ];

  // =========================================================
  // PAGINATION
  // =========================================================

  const totalPages = Math.max(1, Math.ceil(alerts.length / MACHINES_PER_PAGE));

  // If new data changes total pages
  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [currentPage, totalPages]);

  // Machines for current page
  const currentMachines = useMemo(() => {
    const startIndex = (currentPage - 1) * MACHINES_PER_PAGE;

    return alerts.slice(startIndex, startIndex + MACHINES_PER_PAGE);
  }, [alerts, currentPage]);

  // =========================================================
  // NEXT / PREVIOUS
  // =========================================================

  const goToNextPage = () => {
    if (currentPage < totalPages) {
      setCurrentPage((page) => page + 1);
    }
  };

  const goToPreviousPage = () => {
    if (currentPage > 1) {
      setCurrentPage((page) => page - 1);
    }
  };

  // =========================================================
  // CHECK CRITICAL
  // =========================================================

  const isCritical = (status) => {
    return status === "CRITICAL FAULT PREDICTED" || status === "CRITICAL FAULT";
  };

  // =========================================================
  // FORMAT TIME
  // =========================================================

  const formatTime = (timestamp) => {
    if (!timestamp) {
      return "N/A";
    }

    try {
      return new Date(timestamp).toLocaleString();
    } catch {
      return "N/A";
    }
  };

  // =========================================================
  // PAGE MACHINE RANGE
  // =========================================================

  const firstMachine =
    alerts.length === 0 ? 0 : (currentPage - 1) * MACHINES_PER_PAGE + 1;

  const lastMachine = Math.min(currentPage * MACHINES_PER_PAGE, alerts.length);

  // =========================================================
  // UI
  // =========================================================

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6">
      <div className="max-w-7xl mx-auto">
        {/* =================================================
            HEADER
        ================================================= */}

        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8">
          <div>
            <h1 className="text-3xl md:text-4xl font-bold">
              Predictive Maintenance Dashboard
            </h1>

            <p className="text-slate-400 mt-2">
              Real-time machine monitoring and fault prediction
            </p>
          </div>

          {/* CONNECTION STATUS */}

          <div className="flex items-center gap-3">
            <div
              className={`w-3 h-3 rounded-full ${
                connectionStatus === "Live Connected"
                  ? "bg-green-500"
                  : connectionStatus === "Backend Connected"
                    ? "bg-green-500"
                    : "bg-red-500"
              }`}
            ></div>

            <span className="text-sm text-slate-300">{connectionStatus}</span>
          </div>
        </div>

        {/* =================================================
            SUMMARY CARDS
        ================================================= */}

        <div className="grid grid-cols-1 md:grid-cols-3 gap-5 mb-8">
          {/* TOTAL MACHINES */}

          <div className="bg-slate-900 border border-slate-800 rounded-xl p-6">
            <p className="text-slate-400 text-sm">Total Machines</p>

            <h2 className="text-4xl font-bold mt-2">{alerts.length}</h2>

            <p className="text-slate-500 text-sm mt-2">Machines monitored</p>
          </div>

          {/* NORMAL MACHINES */}

          <div className="bg-slate-900 border border-green-900 rounded-xl p-6">
            <div className="flex justify-between items-center">
              <p className="text-slate-400 text-sm">Normal Machines</p>

              <div className="w-3 h-3 bg-green-500 rounded-full"></div>
            </div>

            <h2 className="text-4xl font-bold text-green-400 mt-2">
              {normalCount}
            </h2>

            <p className="text-green-500/70 text-sm mt-2">Operating normally</p>
          </div>

          {/* CRITICAL MACHINES */}

          <div className="bg-slate-900 border border-red-900 rounded-xl p-6">
            <div className="flex justify-between items-center">
              <p className="text-slate-400 text-sm">Critical Machines</p>

              <div className="w-3 h-3 bg-red-500 rounded-full"></div>
            </div>

            <h2 className="text-4xl font-bold text-red-400 mt-2">
              {criticalCount}
            </h2>

            <p className="text-red-500/70 text-sm mt-2">Fault predicted</p>
          </div>
        </div>

        {/* =================================================
            GRAPH
        ================================================= */}

        <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 mb-8">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-5">
            <div>
              <h2 className="text-2xl font-bold">Machine Status Overview</h2>

              <p className="text-slate-400 text-sm mt-1">
                Normal vs critical machine distribution
              </p>
            </div>

            <div className="text-sm text-slate-400 mt-3 md:mt-0">
              Total: {alerts.length}
            </div>
          </div>

          {alerts.length === 0 ? (
            <div className="h-[300px] flex items-center justify-center">
              <p className="text-slate-500">No data available for graph</p>
            </div>
          ) : (
            <div className="w-full h-[320px]">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={chartData}
                    cx="50%"
                    cy="50%"
                    outerRadius={105}
                    innerRadius={55}
                    paddingAngle={3}
                    dataKey="value"
                    label={({ name, value }) => `${name}: ${value}`}
                    labelLine={false}
                  >
                    <Cell fill="#22c55e" />

                    <Cell fill="#ef4444" />
                  </Pie>

                  <Tooltip
                    contentStyle={{
                      backgroundColor: "#0f172a",
                      border: "1px solid #334155",
                      borderRadius: "8px",
                      color: "#ffffff",
                    }}
                  />

                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>

        {/* =================================================
            MACHINE MONITORING HEADER
        ================================================= */}

        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-5">
          <div>
            <h2 className="text-2xl font-semibold">Machine Monitoring</h2>

            <p className="text-slate-400 text-sm mt-1">
              Showing {firstMachine}
              {" - "}
              {lastMachine}
              {" of "}
              {alerts.length}
              {" machines"}
            </p>
          </div>

          <div className="text-sm text-slate-400">20 machines per page</div>
        </div>

        {/* =================================================
            LOADING
        ================================================= */}

        {loading && (
          <div className="flex justify-center items-center py-20">
            <div className="text-slate-400">Loading machine data...</div>
          </div>
        )}

        {/* =================================================
            NO DATA
        ================================================= */}

        {!loading && alerts.length === 0 && (
          <div className="bg-slate-900 border border-slate-800 rounded-xl p-10 text-center">
            <p className="text-slate-400">No machine data available.</p>

            <p className="text-slate-500 text-sm mt-2">
              Start the Java Edge Engine to send machine data.
            </p>
          </div>
        )}

        {/* =================================================
            MACHINE CARDS
        ================================================= */}

        {!loading && currentMachines.length > 0 && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
            {currentMachines.map((machine, index) => {
              const critical = isCritical(machine.status);

              const machineNumber =
                (currentPage - 1) * MACHINES_PER_PAGE + index + 1;

              return (
                <div
                  key={
                    machine._id ||
                    `${machine.productID}-${machine.timestamp}-${index}`
                  }
                  className={`rounded-xl p-5 border transition-all duration-200 ${
                    critical
                      ? "bg-red-950/30 border-red-700 hover:border-red-500"
                      : "bg-slate-900 border-slate-800 hover:border-slate-600"
                  }`}
                >
                  {/* MACHINE HEADER */}

                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <p className="text-xs text-slate-500">
                        Machine #{machineNumber}
                      </p>

                      <h3 className="text-xl font-bold mt-1">
                        {machine.productID}
                      </h3>
                    </div>

                    {/* STATUS */}

                    <span
                      className={`text-xs font-semibold px-2 py-1 rounded-full ${
                        critical
                          ? "bg-red-500/20 text-red-400"
                          : "bg-green-500/20 text-green-400"
                      }`}
                    >
                      {critical ? "CRITICAL" : "NORMAL"}
                    </span>
                  </div>

                  {/* DIVIDER */}

                  <div className="border-t border-slate-800 my-4"></div>

                  {/* TORQUE */}

                  <div className="flex justify-between mb-3">
                    <span className="text-slate-400">Torque</span>

                    <span
                      className={`font-semibold ${
                        Number(machine.torque) > 60
                          ? "text-red-400"
                          : "text-white"
                      }`}
                    >
                      {Number(machine.torque).toFixed(2)} Nm
                    </span>
                  </div>

                  {/* TOOL WEAR */}

                  <div className="flex justify-between mb-3">
                    <span className="text-slate-400">Tool Wear</span>

                    <span
                      className={`font-semibold ${
                        Number(machine.toolWear) > 200
                          ? "text-red-400"
                          : "text-white"
                      }`}
                    >
                      {machine.toolWear}
                    </span>
                  </div>

                  {/* RPM */}

                  <div className="flex justify-between mb-3">
                    <span className="text-slate-400">RPM</span>

                    <span className="font-semibold">
                      {machine.rotationalSpeed}
                    </span>
                  </div>

                  {/* PRIORITY */}

                  <div className="flex justify-between mb-3">
                    <span className="text-slate-400">Priority</span>

                    <span
                      className={`font-bold ${
                        critical ? "text-red-400" : "text-green-400"
                      }`}
                    >
                      {critical ? "10" : "1"}
                    </span>
                  </div>

                  {/* STATUS MESSAGE */}

                  <div
                    className={`mt-4 p-3 rounded-lg text-center text-sm font-medium ${
                      critical
                        ? "bg-red-500/10 text-red-400"
                        : "bg-green-500/10 text-green-400"
                    }`}
                  >
                    {critical ? "CRITICAL FAULT PREDICTED" : "NORMAL"}
                  </div>

                  {/* TIMESTAMP */}

                  <p className="text-xs text-slate-600 mt-4">
                    {formatTime(machine.timestamp)}
                  </p>
                </div>
              );
            })}
          </div>
        )}

        {/* =================================================
            PAGINATION
        ================================================= */}

        {!loading && alerts.length > 0 && (
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 mt-8">
            {/* PREVIOUS */}

            <button
              onClick={goToPreviousPage}
              disabled={currentPage === 1}
              className="px-6 py-3 rounded-lg bg-slate-800 text-white font-medium hover:bg-slate-700 disabled:opacity-40 disabled:cursor-not-allowed transition"
            >
              ← Previous
            </button>

            {/* PAGE NUMBER */}

            <div className="px-5 py-3 bg-slate-900 border border-slate-800 rounded-lg">
              <span className="text-slate-400">Page </span>

              <span className="font-bold">{currentPage}</span>

              <span className="text-slate-400"> of </span>

              <span className="font-bold">{totalPages}</span>
            </div>

            {/* NEXT */}

            <button
              onClick={goToNextPage}
              disabled={currentPage === totalPages}
              className="px-6 py-3 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-500 disabled:opacity-40 disabled:cursor-not-allowed transition"
            >
              Next →
            </button>
          </div>
        )}

        {/* =================================================
            FOOTER
        ================================================= */}

        <div className="text-center text-slate-600 text-sm mt-10 pb-5">
          Predictive Maintenance System
          {" • "}
          Real-time Machine Monitoring
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
